	groupCreateCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	groupCreateCmd.Flags().String("name", "", "The group to add, such as developers")
	_ = groupCreateCmd.MarkFlagRequired("name")
	groupCreateCmd.Flags().Int("gid", 0, "Its numeric group ID; the system assigns one when it is 0")
	groupCreateCmd.Flags().Bool("system", false, "Add it as a system group, with an ID from the system range")
	groupUpdateCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	groupUpdateCmd.Flags().String("name", "", "The group, such as developers")
	_ = groupUpdateCmd.MarkFlagRequired("name")
	groupUpdateCmd.Flags().StringSlice("members", nil, "Its members, which replace the members it has; none when empty")
